<script setup lang="ts">
import SubsidyHistory from './SubsidyHistory.vue'
import {computed,ref,reactive}from'vue'
import{useRoute}from'vue-router'
import RecordPage from '../../components/RecordPage.vue';import type {Definition,Row} from '../../shared/records'
import PrivateUpload from '../../components/PrivateUpload.vue'
import{http}from'../../api/http'
const route=useRoute(),tab=ref(String(useRoute().query.tab??'elders')),dialog=ref(''),selected=ref<Row|null>(null),form=reactive<Row>({}),error=ref(''),pending=ref(false),record=ref<InstanceType<typeof RecordPage>>()
const bindingStatus=ref('PENDING'),revokeTarget=ref<Row|null>(null),revokeNote=ref(''),historyElder=ref<number>()
async function revoke(){pending.value=true;error.value='';try{await http.post('/bindings/'+revokeTarget.value!.id+'/revoke',{note:revokeNote.value});revokeTarget.value=null;await record.value?.load()}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
const allergens=ref<Row[]>([]),categories=ref<Row[]>([])
const community=computed(()=>route.path.startsWith('/community')),kind=computed(()=>route.path.endsWith('/subsidies')?'subsidies':tab.value)
const definition=computed<Definition>(()=>{
 if(kind.value==='history')return {title:'绑定变更历史',endpoint:'/bindings/history',columns:[['elderName','老人'],['action','办理动作'],['status','状态'],['note','原因'],['createdAt','办理时间']]}
 if(kind.value==='bindings')return community.value?{title:'家属绑定审核',endpoint:'/bindings?status='+(bindingStatus.value??'')+'&siteId='+String(route.query.siteId??''),columns:[['elderName','老人'],['familyName','申请家属'],['status','状态'],['createdAt','申请时间']]}:{title:'老人绑定',endpoint:'/family/bindings',createOnly:true,columns:[['elderId','老人编号'],['elderName','老人'],['status','状态'],['reviewNote','审核意见']],fields:[{key:'elderId',label:'老人编号（向社区获取）',type:'number'},{key:'proofFileIds',label:'关系证明',type:'files',purpose:'BINDING'}],save:body=>http.post('/family/bindings',{elderId:body.elderId,proofFileId:body.proofFileIds?.[0]})}
 if(kind.value==='subsidies')return{title:'补贴申请与审核',endpoint:'/subsidy-applications?status='+String(route.query.status??'')+'&siteId='+String(route.query.siteId??''),createOnly:true,columns:[['elderName','老人'],['status','状态'],['reviewNote','审核意见'],['createdAt','申请时间']],fields:[{key:'elderId',label:'老人',type:'select',source:'/elders?size=100'},{key:'proofFileIds',label:'资格材料',type:'files',purpose:'SUBSIDY'}]}
 return{title:community.value?'老人档案':'我的老人',endpoint:'/elders',columns:[['id','老人编号'],['name','姓名'],['siteName','服务网点'],['birthDate','出生日期'],['approvalStatus','建档状态'],['status','服务状态']],fields:[{key:'name',label:'老人姓名'},{key:'siteId',label:'服务网点',type:'select',source:'/service-sites'},{key:'birthDate',label:'出生日期',type:'date'},{key:'phone',label:'新联系电话（留空保留）'},{key:'identityNumber',label:'证件号码（加密保存，留空保留）'},...(community.value?[{key:'status',label:'服务状态',type:'select',initial:'ACTIVE',options:[{value:'ACTIVE',label:'启用'},{value:'DISABLED',label:'停用'}]}]:[])]}
})
async function health(row:Row){try{selected.value=row;error.value='';const [data,allergenData,categoryData]=await Promise.all([http.get<never,Row>(`/elders/${row.id}/health`),http.get<never,Row[]>('/allergens'),http.get<never,Row[]>('/dish-categories')]);Object.assign(form,data);allergens.value=allergenData.filter(v=>v.isActive!==false&&v.isActive!==0);categories.value=categoryData;for(const key of ['diseaseCodes','avoidIngredientNames'])form[key]=(form[key]??[]).join('，');dialog.value='health'}catch(e){error.value=(e as Error).message}}
function review(row:Row,type:string){selected.value=row;form.note='';form.validFrom='';form.validTo='';dialog.value=type;error.value=''}
async function save(approve=true){if(pending.value)return;pending.value=true;error.value='';try{if(dialog.value==='health'){const body:Row={};for(const key of ['allergenIds','preferredCategoryIds','dislikedCategoryIds'])body[key]=form[key]??[];for(const key of ['diseaseCodes','avoidIngredientNames'])body[key]=String(form[key]??'').split(/[,，]/).map(v=>v.trim()).filter(Boolean);body.allergenDataComplete=!!form.allergenDataComplete;body.healthDataComplete=!!form.healthDataComplete;body.healthNotes=form.healthNotes??'';await http.put(`/elders/${selected.value!.id}/health`,body)}else await http.post(`/${dialog.value==='binding'?'bindings':'subsidy-applications'}/${selected.value!.id}/${approve?'approve':'reject'}`,{note:form.note,...dialog.value==='subsidy'?{validFrom:form.validFrom||null,validTo:form.validTo||null}:{}});dialog.value='';await record.value?.load()}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
</script>
<template><div><div v-if="!route.path.endsWith('/subsidies')" class="toolbar"><el-button @click="tab='elders'">老人档案</el-button><el-button @click="tab='bindings'">{{community?'绑定审核':'绑定已有老人'}}</el-button><el-button @click="tab='subsidies'">补贴申请</el-button><el-button @click="tab='history'">绑定历史</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="community&&kind==='bindings'" class="toolbar"><el-select v-model="bindingStatus" clearable aria-label="绑定状态"><el-option label="待审核" value="PENDING"/><el-option label="已通过" value="APPROVED"/><el-option label="已撤销" value="REVOKED"/></el-select></div><RecordPage ref="record" :definition="definition"><template #actions="{row}"><el-button v-if="kind==='elders'&&row.approvalStatus!=='PENDING'" link @click="historyElder=row.id">补贴资格与历史</el-button><el-button v-if="kind==='bindings'&&['PENDING','APPROVED'].includes(row.status)" link @click="revokeTarget=row;revokeNote=''">{{community?'撤销绑定':'撤回或解除绑定'}}</el-button><el-button v-if="kind==='elders'&&row.approvalStatus!=='PENDING'" link type="primary" @click="health(row)">健康与饮食偏好</el-button><el-button v-if="community&&['bindings','subsidies'].includes(kind)&&row.status==='PENDING'" link type="primary" @click="review(row,kind==='bindings'?'binding':'subsidy')">审核</el-button></template></RecordPage>
<el-dialog :model-value="!!dialog" :title="dialog==='health'?'健康与饮食偏好':'申请审核'" width="min(660px,94vw)" @close="dialog=''">
<el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="form-stack" @submit.prevent="save(true)"><template v-if="dialog==='health'"><template v-for="[key,label] in [['diseaseCodes','基础疾病标签（与社区确认）'],['avoidIngredientNames','禁忌食材']]" :key="key"><label :for="'health-'+key">{{label}}（逗号分隔）</label><el-input :id="'health-'+key" v-model="form[key!]"/></template><template v-for="[key,label] in [['allergenIds','过敏原'],['preferredCategoryIds','偏好菜品分类'],['dislikedCategoryIds','不喜欢的菜品分类']]" :key="key"><label>{{label}}</label><el-select v-model="form[key!]" multiple clearable :aria-label="label"><el-option v-for="item in key==='allergenIds'?allergens:categories" :key="item.id" :value="item.id" :label="item.name"/></el-select></template><el-checkbox v-model="form.allergenDataComplete">过敏原信息已完整核对</el-checkbox><el-checkbox v-model="form.healthDataComplete">健康资料已完整核对</el-checkbox><label for="health-note">补充说明</label><el-input id="health-note" v-model="form.healthNotes" type="textarea"/></template><template v-else><PrivateUpload v-if="selected?.proofFileId" :model-value="[selected.proofFileId]" purpose="BINDING" readonly/><PrivateUpload v-if="selected?.proofFileIds?.length" :model-value="selected.proofFileIds" purpose="SUBSIDY" readonly/><template v-if="dialog==='subsidy'"><label for="subsidy-valid-from">补贴生效日期（留空为今天）</label><el-input id="subsidy-valid-from" v-model="form.validFrom" type="date"/><label for="subsidy-valid-to">补贴结束日期（可选）</label><el-input id="subsidy-valid-to" v-model="form.validTo" type="date"/></template><label for="review-note">审核意见（必填）</label><el-input id="review-note" v-model="form.note" type="textarea"/></template><div class="toolbar"><el-button native-type="submit" type="primary" :loading="pending">{{dialog==='health'?'保存':'审核通过'}}</el-button><el-button v-if="dialog!=='health'" type="danger" :loading="pending" @click="save(false)">驳回</el-button></div></form></el-dialog><el-dialog :model-value="!!revokeTarget" title="撤销家属绑定" @close="revokeTarget=null"><p>解除后该家属将不能查看此老人档案和订单，历史资金记录保留。</p><label for="revoke-note">撤销原因</label><el-input id="revoke-note" v-model="revokeNote"/><el-button :disabled="!revokeNote.trim()" :loading="pending" @click="revoke">确认撤销</el-button></el-dialog><el-dialog :model-value="!!historyElder" title="补贴资格与历史" width="min(800px,94vw)" @close="historyElder=undefined"><SubsidyHistory v-if="historyElder" :elder-id="historyElder" :staff="community"/></el-dialog></div></template>
